    const val K_PUBLISHED = 0.4514285714285714
    const val DROPS_4X5_ESTIMATE = 10.0
    const val DROPS_QR_ESTIMATE = 220.0

    /** true si la base documentada de la tinta tiene factor oficial (V4238 y V4251 no lo tienen). */
    fun hasOfficialBase(ink: String): Boolean {
        val base = inks[ink] ?: return true
        return inkBases.containsKey(base)
    }

    fun inksFor(group: String): List<String> {
        val label = INK_GROUP_TABLE[group] ?: INK_GROUP_TABLE["std"] ?: ""
        val key = label.replace("\\s".toRegex(), "").lowercase()
        return inkGroups[key] ?: inks.keys.toList()
    }

    private val INK_GROUP_TABLE = mapOf(
        "1040" to "1040",
        "1240" to "1240",
        "1280" to "1280",
        "1580" to "1580",
        "1580C" to "1580C",
        "1880+" to "1880\n1880+",
        "1880UHS" to "1880UHS",
        "1880HR" to "1880HR",
        "1710" to "1710",
        "1620UHS" to "1620UHS\n1650UHS",
        "1620HR" to "1620HR\n1650HR",
        "std" to "1210\n1220\n1510\n1520\n1530\n1550\n1560\n1610\n1620\n1630\n1650\n1660\n1610DH",
